const https = require('https');
const http = require('http');

async function checkEndpoint(url) {
  return new Promise((resolve) => {
    const client = url.startsWith('https') ? https : http;
    const req = client.get(url, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        resolve({
          url,
          status: res.statusCode,
          statusText: res.statusMessage,
          headers: res.headers,
          body: data
        });
      });
    });

    req.on('error', (error) => {
      resolve({
        url,
        error: true,
        errorMessage: error.message
      });
    });

    req.setTimeout(10000, () => {
      req.destroy();
      resolve({
        url,
        error: true,
        errorMessage: 'Request timeout'
      });
    });
  });
}

async function main() {
  console.log('Checking service dependencies connectivity...\n');

  const endpoints = [
    'http://localhost:47301/checkConnectivity?variant=1',
    'https://httpstat.us/200'
  ];

  const results = [];

  for (const endpoint of endpoints) {
    console.log(`Testing: ${endpoint}`);
    const result = await checkEndpoint(endpoint);
    results.push(result);

    if (result.error) {
      console.log(`  ❌ ERROR: ${result.errorMessage}`);
    } else {
      console.log(`  ✅ Status: ${result.status} ${result.statusText}`);
      console.log(`  Content-Type: ${result.headers['content-type'] || 'N/A'}`);
      if (result.body && result.body.length < 500) {
        console.log(`  Response: ${result.body.substring(0, 200)}${result.body.length > 200 ? '...' : ''}`);
      }
    }
    console.log();
  }

  console.log('=== Summary ===');
  results.forEach((result, index) => {
    console.log(`${index + 1}. ${result.url}`);
    if (result.error) {
      console.log(`   Status: ❌ Unhealthy - ${result.errorMessage}`);
    } else {
      console.log(`   Status: ✅ Healthy - HTTP ${result.status}`);
      console.log(`   Response: ${result.status === 200 ? 'Success' : `HTTP ${result.status}`}`);
    }
    console.log();
  });
}

main().catch(console.error);

const https = require('https');

async function checkHttpstat() {
  return new Promise((resolve) => {
    const options = {
      timeout: 5000
    };

    const req = https.get('https://httpstat.us/200', options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        resolve({
          url: 'https://httpstat.us/200',
          status: res.statusCode,
          statusText: res.statusMessage,
          headers: res.headers,
          body: data
        });
      });
    });

    req.on('error', (error) => {
      resolve({
        url: 'https://httpstat.us/200',
        error: true,
        errorMessage: error.message
      });
    });

    req.setTimeout(5000, () => {
      req.destroy();
      resolve({
        url: 'https://httpstat.us/200',
        error: true,
        errorMessage: 'Request timeout'
      });
    });
  });
}

async function main() {
  console.log('Testing https://httpstat.us/200 specifically...\n');
  const result = await checkHttpstat();

  console.log(`URL: ${result.url}`);
  if (result.error) {
    console.log(`❌ ERROR: ${result.errorMessage}`);
  } else {
    console.log(`✅ Status: ${result.status} ${result.statusText}`);
    console.log(`Content-Type: ${result.headers['content-type'] || 'N/A'}`);
    console.log(`Response: ${result.body}`);
  }
}

main().catch(console.error);

